buggyCode:
record Order(String id, List<String> items) {}

List<String> items = new ArrayList<>(List.of("ao"));
Order order = new Order("A1", items);
Set<Order> pending = new HashSet<>(Set.of(order));

items.add("quan"); // bước gom hàng thêm món

System.out.println(order);
System.out.println(pending.contains(order));
System.out.println(pending.contains(new Order("A1", List.of("ao", "quan"))));
System.out.println("size=" + pending.size());

fix.code:
record Order(String id, List<String> items) {
    Order {
        Objects.requireNonNull(id);
        items = List.copyOf(items); // bản sao bất biến, từ chối null
    }

    Order withItem(String item) {
        var next = new ArrayList<>(items);
        next.add(item);
        return new Order(id, next);
    }
}
